-- Generated by scripts/build-coven-program-templates.mjs. Do not edit by hand.
-- The ready-made coven programs: an initiation and a training program for each
-- holiday calendar, copied into a coven as drafts (copy_coven_program_template).

insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('wheel-initiation', 'initiation', 'wheel', 'Wheel of the Year: a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every sabbat of the Wheel of the Year.', 'A traditional year and a day of study, practice and service before initiation, shaped around the Wheel of the Year.

Each stage builds on the one before. Some tasks you sign off yourself; your mentor signs off most; the coven’s leaders confirm the oath and the initiation itself.

Change anything to fit your coven: rename stages, add your own lore, set how long each stage takes, and choose who signs each task off.', '[{"title":"The threshold","intro":"Welcome. In this first stage you meet your mentor, read what the coven holds to, and set down why you seek the Wheel of the Year.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Meet your mentor","kind":"meeting","instructions":"Arrange a first conversation with your mentor. Talk about what drew you here, what you hope to learn, and how you’ll keep in touch through the year.","times":1,"response":"none","checked_by":"mentor"},{"title":"Read the coven’s creed, rules and agreements","kind":"study","instructions":"Read every page the coven has written, and ask your mentor about anything that isn’t clear.","times":1,"response":"none","checked_by":"self"},{"title":"Why I seek this path","kind":"reflection","instructions":"Write a page on why you seek the Wheel of the Year, what you already practise, and what you hope the year will open.","times":1,"response":"text","checked_by":"mentor"},{"title":"Begin a magical diary","kind":"practice","instructions":"Start a diary you’ll keep all year: dreams, workings, moods, the weather, the moon. Write in it at least once a week.","times":1,"response":"none","checked_by":"self"},{"title":"Set up your personal altar","kind":"practice","instructions":"Make an altar with the four elements and a candle for the divine at home. Describe it, and why you chose what’s on it.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Foundations","intro":"The skills everything else rests on: steadying yourself, keeping your space clean and warded, and making sacred space well.","min_days":90,"passed_by":"mentor","tasks":[{"title":"Ground and centre daily","kind":"practice","instructions":"Ground and centre every day for thirty days: breath, roots, a calm centre. Log each day you do it.","times":30,"response":"none","checked_by":"self","minutes":10},{"title":"Cleanse and ward your home","kind":"practice","instructions":"Cleanse your home and set wards in the coven’s way. Write what you used and how the space felt before and after.","times":1,"response":"text","checked_by":"mentor"},{"title":"Make sacred space","kind":"practice","instructions":"Learn to cast and close a circle, calling the quarters and the elements. Do it three times, then show your mentor.","times":3,"response":"none","checked_by":"mentor"},{"title":"The elements and the directions","kind":"study","instructions":"Study the elements (or the coven’s equivalent) and their correspondences: directions, colours, tools, times. Write a page for each.","times":1,"response":"text","checked_by":"mentor"},{"title":"Ethics and consent","kind":"reflection","instructions":"Write on the ethics of magic: harm, consent, working for others, and what you will and won’t do. Talk it through with your mentor.","times":1,"response":"text","checked_by":"mentor"},{"title":"Meditation and trance","kind":"practice","instructions":"Practise meditation or light trance twelve times, building from ten minutes to thirty.","times":12,"response":"none","checked_by":"self"}]},{"title":"Turning the year","intro":"A year and a day of the Wheel of the Year. Keep each sabbat as it comes and learn the eight sabbats, the turning of the seasons and the myth cycle your coven tells. This stage lasts at least a year and a day.","min_days":366,"passed_by":"mentor","tasks":[{"title":"Keep Imbolc","kind":"ritual","instructions":"Keep Imbolc with the coven, or on your own if the coven isn’t gathering.\n\nThe first stirrings of spring as the ewes come into milk. A festival of Brigid, hearth fire and holy wells: cleansing, inspiration and new beginnings.\n\nAfterwards, write what you did, what you noticed, and what Imbolc means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/imbolc"},{"title":"Keep Ostara","kind":"ritual","instructions":"Keep Ostara with the coven, or on your own if the coven isn’t gathering.\n\nThe spring equinox, when day and night stand in balance. A celebration of seeds, eggs and greening earth: growth, fertility and renewal.\n\nAfterwards, write what you did, what you noticed, and what Ostara means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/ostara"},{"title":"Keep Beltane","kind":"ritual","instructions":"Keep Beltane with the coven, or on your own if the coven isn’t gathering.\n\nThe flowering height of spring. A fire festival of passion, fertility and union, of maypoles and bonfires, when life is at its most abundant.\n\nAfterwards, write what you did, what you noticed, and what Beltane means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/beltane"},{"title":"Keep Litha","kind":"ritual","instructions":"Keep Litha with the coven, or on your own if the coven isn’t gathering.\n\nThe summer solstice and longest day, the sun at the peak of its power: strength, abundance, celebration, and the turn toward the waning year.\n\nAfterwards, write what you did, what you noticed, and what Litha means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/litha"},{"title":"Keep Lammas","kind":"ritual","instructions":"Keep Lammas with the coven, or on your own if the coven isn’t gathering.\n\nThe first harvest, of grain and bread. Giving thanks for what has ripened and sharing the first loaf, in honor of Lugh and the generous land.\n\nAfterwards, write what you did, what you noticed, and what Lammas means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/lammas"},{"title":"Keep Mabon","kind":"ritual","instructions":"Keep Mabon with the coven, or on your own if the coven isn’t gathering.\n\nThe autumn equinox and second harvest, when day and night are balanced again: gratitude, sharing the bounty, and preparing for the dark half of the year.\n\nAfterwards, write what you did, what you noticed, and what Mabon means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/mabon"},{"title":"Keep Samhain","kind":"ritual","instructions":"Keep Samhain with the coven, or on your own if the coven isn’t gathering.\n\nThe witches’ new year, when the veil between the worlds is thin: a time to honor the ancestors and the beloved dead, and to rest as the dark half of the year begins.\n\nAfterwards, write what you did, what you noticed, and what Samhain means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/samhain"},{"title":"Keep Yule","kind":"ritual","instructions":"Keep Yule with the coven, or on your own if the coven isn’t gathering.\n\nThe winter solstice and longest night. The sun is reborn and the light begins to return: a time of candles, evergreens, hope and renewal.\n\nAfterwards, write what you did, what you noticed, and what Yule means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"wheel/yule"},{"title":"Keep the full moons","kind":"attend","instructions":"Keep thirteen full-moon esbats across the year, with the coven when it gathers and alone when it does not.","times":13,"response":"none","checked_by":"mentor"},{"title":"The lore of the year","kind":"study","instructions":"Study the eight sabbats, the turning of the seasons and the myth cycle your coven tells. Write a short account in your own words.","times":1,"response":"text","checked_by":"mentor"},{"title":"Divination","kind":"practice","instructions":"Learn one form of divination your coven uses. Do a reading every week for three months and keep a record of what came true.","times":12,"response":"none","checked_by":"self"},{"title":"Relationship with the divine","kind":"reflection","instructions":"Keep a devotional practice to the God and Goddess, or the powers your coven honours. At the half-year, write about the relationship as it’s growing.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Service","intro":"A coven is kept by its members. Give your craft and your time to the circle.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Write a page for the coven’s book","kind":"book","instructions":"Write a page for the coven’s Book of Shadows on something you’ve learned this year: a working, a recipe, a piece of lore. Send it for approval.","times":1,"response":"none","checked_by":"manager"},{"title":"Serve at coven rites","kind":"service","instructions":"Help prepare and clear away at two coven rites: setting the altar, bringing what’s needed, welcoming others.","times":2,"response":"none","checked_by":"mentor"},{"title":"Lead a part of a ritual","kind":"ritual","instructions":"Take one part of a coven ritual: calling a quarter, leading a chant, a reading, lighting the altar.","times":1,"response":"none","checked_by":"mentor"},{"title":"A service to the wider community","kind":"service","instructions":"Do something for people or land beyond the coven: a clean-up, a donation, help for someone in need. Write what you did.","times":1,"response":"text","checked_by":"mentor","optional":true}]},{"title":"Dedication and initiation","intro":"The end of the year and a day. You and the coven’s leaders decide together that you are ready.","min_days":0,"passed_by":"manager","tasks":[{"title":"A final conversation with your mentor","kind":"meeting","instructions":"Look back on the year with your mentor: what changed, what’s still to learn, and whether you are ready.","times":1,"response":"none","checked_by":"mentor"},{"title":"Write your oath","kind":"oath","instructions":"Write the oath you will take at your initiation, in your own words, and share it with the coven’s leaders.","times":1,"response":"text","checked_by":"manager"},{"title":"Initiation","kind":"ritual","instructions":"Your initiation into the coven, held by its leaders in the way of the Wheel of the Year.","times":1,"response":"none","checked_by":"manager"}]}]'::jsonb, 0)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('wheel-training', 'training', 'wheel', 'Wheel of the Year: foundations of the craft', 'Core training for members of a coven following the Wheel of the Year, at your own pace.', 'Eight modules of core skills for the Wheel of the Year, from energy work to writing a full ritual.

Members can take the modules alongside an initiation program or on their own. Mentors sign off most tasks; the last module is reviewed by the coven’s leaders.', '[{"title":"Energy and self","intro":"Feel, raise, direct and release energy, and keep yourself clear.","passed_by":"mentor","tasks":[{"title":"Grounding and centring","kind":"practice","instructions":"Practise grounding and centring until you can do it in under a minute. Log ten sessions.","times":10,"response":"none","checked_by":"self"},{"title":"Raising and directing energy","kind":"practice","instructions":"Raise energy by breath, chant or movement, direct it into an object, then release and ground what’s left. Describe what you felt.","times":1,"response":"text","checked_by":"mentor"},{"title":"Shielding","kind":"practice","instructions":"Learn a shielding method and use it every day for a week.","times":7,"response":"none","checked_by":"self"}]},{"title":"Sacred space","intro":"How to cast and close a circle, calling the quarters and the elements, and how to close it again cleanly.","passed_by":"mentor","tasks":[{"title":"Make and close sacred space","kind":"practice","instructions":"Learn the coven’s way to cast and close a circle, calling the quarters and the elements. Do it five times.","times":5,"response":"none","checked_by":"mentor"},{"title":"Purification","kind":"practice","instructions":"Learn the coven’s purification before ritual and use it before every working this month.","times":4,"response":"none","checked_by":"self"},{"title":"Write it down","kind":"book","instructions":"Write out the coven’s way of making sacred space as you now do it, for your own book.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Tools and the altar","intro":"The tools your coven uses, how to cleanse and consecrate them, and how to keep an altar.","passed_by":"mentor","tasks":[{"title":"Your altar","kind":"practice","instructions":"Keep an altar with the four elements and a candle for the divine. Tend it weekly for a month.","times":4,"response":"none","checked_by":"self"},{"title":"Consecrate a tool","kind":"ritual","instructions":"Cleanse and consecrate one working tool. Write what you did and why.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Correspondences, herbs and stones","intro":"What things are for: plants, stones, colours, days and planetary hours.","passed_by":"mentor","tasks":[{"title":"Twelve plants","kind":"study","instructions":"Learn twelve plants your coven works with: their uses, cautions and lore. Keep a page for each.","times":12,"response":"none","checked_by":"self"},{"title":"Seven stones","kind":"study","instructions":"Learn seven stones and how to cleanse and charge them.","times":7,"response":"none","checked_by":"self"},{"title":"Days and hours","kind":"study","instructions":"Learn the planetary days and hours and when to use them. Plan one working by them.","times":1,"response":"text","checked_by":"mentor"},{"title":"Herbal safety","kind":"reflection","instructions":"Write which herbs and oils need care (pregnancy, pets, skin, ingestion) and how you’ll check before using something new.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Divination","intro":"Read for yourself and, later, for others.","passed_by":"mentor","tasks":[{"title":"Learn a system","kind":"study","instructions":"Choose a system (tarot, runes, ogham, oracle, scrying) and learn its basics.","times":1,"response":"text","checked_by":"mentor"},{"title":"Daily draws","kind":"practice","instructions":"Draw or cast daily for thirty days and note what each meant by evening.","times":30,"response":"none","checked_by":"self"},{"title":"Read for your mentor","kind":"practice","instructions":"Give your mentor a reading and talk through it together.","times":1,"response":"none","checked_by":"mentor"}]},{"title":"Gods, spirits and ancestors","intro":"Build relationship with the God and Goddess, or the powers your coven honours.","passed_by":"mentor","tasks":[{"title":"A devotional practice","kind":"practice","instructions":"Keep a short daily devotion (an offering, a prayer, a candle) for a month.","times":30,"response":"none","checked_by":"self"},{"title":"Honour your ancestors","kind":"ritual","instructions":"Make a place for your ancestors (of blood, of spirit or of craft) and honour them. Write about who you honoured.","times":1,"response":"text","checked_by":"mentor"},{"title":"Discernment","kind":"reflection","instructions":"Write how you tell a real experience from wishful thinking, and when to ask for help.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"The year’s lore","intro":"Learn the eight sabbats, the turning of the seasons and the myth cycle your coven tells.","passed_by":"mentor","tasks":[{"title":"The lore of Imbolc","kind":"study","instructions":"Learn the history, customs and meaning of Imbolc: The first stirrings of spring as the ewes come into milk. A festival of Brigid, hearth fire and holy wells: cleansing, inspiration and new beginnings. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/imbolc"},{"title":"The lore of Ostara","kind":"study","instructions":"Learn the history, customs and meaning of Ostara: The spring equinox, when day and night stand in balance. A celebration of seeds, eggs and greening earth: growth, fertility and renewal. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/ostara"},{"title":"The lore of Beltane","kind":"study","instructions":"Learn the history, customs and meaning of Beltane: The flowering height of spring. A fire festival of passion, fertility and union, of maypoles and bonfires, when life is at its most abundant. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/beltane"},{"title":"The lore of Litha","kind":"study","instructions":"Learn the history, customs and meaning of Litha: The summer solstice and longest day, the sun at the peak of its power: strength, abundance, celebration, and the turn toward the waning year. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/litha"},{"title":"The lore of Lammas","kind":"study","instructions":"Learn the history, customs and meaning of Lammas: The first harvest, of grain and bread. Giving thanks for what has ripened and sharing the first loaf, in honor of Lugh and the generous land. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/lammas"},{"title":"The lore of Mabon","kind":"study","instructions":"Learn the history, customs and meaning of Mabon: The autumn equinox and second harvest, when day and night are balanced again: gratitude, sharing the bounty, and preparing for the dark half of the year. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/mabon"},{"title":"The lore of Samhain","kind":"study","instructions":"Learn the history, customs and meaning of Samhain: The witches’ new year, when the veil between the worlds is thin: a time to honor the ancestors and the beloved dead, and to rest as the dark half of the year begins. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/samhain"},{"title":"The lore of Yule","kind":"study","instructions":"Learn the history, customs and meaning of Yule: The winter solstice and longest night. The sun is reborn and the light begins to return: a time of candles, evergreens, hope and renewal. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"wheel/yule"}]},{"title":"Ritual craft","intro":"Bring it all together: write and lead a ritual of your own.","passed_by":"manager","tasks":[{"title":"Write a ritual","kind":"book","instructions":"Write a complete ritual for the coven: its purpose, sacred space, the working, the words and the closing.","times":1,"response":"text","checked_by":"manager"},{"title":"Lead it","kind":"ritual","instructions":"Lead your ritual for the coven or a few members, with your mentor present.","times":1,"response":"none","checked_by":"manager"},{"title":"Look back","kind":"reflection","instructions":"Write what went well, what you’d change, and what the training has given you.","times":1,"response":"text","checked_by":"mentor"}]}]'::jsonb, 1)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
