insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('wheel_south-initiation', 'initiation', 'wheel_south', 'Wheel of the Year (Southern Hemisphere): a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every sabbat of the Wheel of the Year.', 'A traditional year and a day of study, practice and service before initiation, shaped around the Wheel of the Year.

