insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('norse-initiation', 'initiation', 'norse', 'Norse & Heathen: a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every blót of Heathen practice and the old Norse year.', 'A traditional year and a day of study, practice and service before initiation, shaped around Heathen practice and the old Norse year.

Each stage builds on the one before. Some tasks you sign off yourself; your mentor signs off most; the coven’s leaders confirm the oath and the initiation itself.

Change anything to fit your coven: rename stages, add your own lore, set how long each stage takes, and choose who signs each task off.', '[{"title":"The threshold","intro":"Welcome. In this first stage you meet your mentor, read what the coven holds to, and set down why you seek Heathen practice and the old Norse year.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Meet your mentor","kind":"meeting","instructions":"Arrange a first conversation with your mentor. Talk about what drew you here, what you hope to learn, and how you’ll keep in touch through the year.","times":1,"response":"none","checked_by":"mentor"},{"title":"Read the coven’s creed, rules and agreements","kind":"study","instructions":"Read every page the coven has written, and ask your mentor about anything that isn’t clear.","times":1,"response":"none","checked_by":"self"},{"title":"Why I seek this path","kind":"reflection","instructions":"Write a page on why you seek Heathen practice and the old Norse year, what you already practise, and what you hope the year will open.","times":1,"response":"text","checked_by":"mentor"},{"title":"Begin a magical diary","kind":"practice","instructions":"Start a diary you’ll keep all year: dreams, workings, moods, the weather, the moon. Write in it at least once a week.","times":1,"response":"none","checked_by":"self"},{"title":"Set up your personal altar","kind":"practice","instructions":"Make a stalli (household altar) with a bowl for offerings and a place for the ancestors at home. Describe it, and why you chose what’s on it.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Foundations","intro":"The skills everything else rests on: steadying yourself, keeping your space clean and warded, and making sacred space well.","min_days":90,"passed_by":"mentor","tasks":[{"title":"Ground and centre daily","kind":"practice","instructions":"Ground and centre every day for thirty days: breath, roots, a calm centre. Log each day you do it.","times":30,"response":"none","checked_by":"self","minutes":10},{"title":"Cleanse and ward your home","kind":"practice","instructions":"Cleanse your home and set wards in the coven’s way. Write what you used and how the space felt before and after.","times":1,"response":"text","checked_by":"mentor"},{"title":"Make sacred space","kind":"practice","instructions":"Learn to hallow a space (by fire, hammer or the coven’s own way) and hold a sumbel. Do it three times, then show your mentor.","times":3,"response":"none","checked_by":"mentor"},{"title":"The elements and the directions","kind":"study","instructions":"Study the elements (or the coven’s equivalent) and their correspondences: directions, colours, tools, times. Write a page for each.","times":1,"response":"text","checked_by":"mentor"},{"title":"Ethics and consent","kind":"reflection","instructions":"Write on the ethics of magic: harm, consent, working for others, and what you will and won’t do. Talk it through with your mentor.","times":1,"response":"text","checked_by":"mentor"},{"title":"Meditation and trance","kind":"practice","instructions":"Practise meditation or light trance twelve times, building from ten minutes to thirty.","times":12,"response":"none","checked_by":"self"}]},{"title":"Turning the year","intro":"A year and a day of Heathen practice and the old Norse year. Keep each blót as it comes and learn the blóts of the year, the Winter Nights and Yule, the Eddas, and gifting for a gift. This stage lasts at least a year and a day.","min_days":366,"passed_by":"mentor","tasks":[{"title":"Keep Þorrablót","kind":"ritual","instructions":"Keep Þorrablót with the coven, or on your own if the coven isn’t gathering.\n\nThe midwinter feast at the start of the old Icelandic month of Þorri (Bóndadagur), honoring Þorri, the spirit of winter, with traditional foods and toasts.\n\nAfterwards, write what you did, what you noticed, and what Þorrablót means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/thorrablot"},{"title":"Keep Dísablót","kind":"ritual","instructions":"Keep Dísablót with the coven, or on your own if the coven isn’t gathering.\n\nOfferings to the dísir, the ancestral mothers and guardian spirits of the family, in late winter, as at the Dísting held at Uppsala around the February full moon.\n\nAfterwards, write what you did, what you noticed, and what Dísablót means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/disablot"},{"title":"Keep Sigrblót · Sumardagurinn fyrsti","kind":"ritual","instructions":"Keep Sigrblót · Sumardagurinn fyrsti with the coven, or on your own if the coven isn’t gathering.\n\nThe first day of summer in the Icelandic year. The sagas tell of a blót at summer’s start “for victory”, for the season of voyages and undertakings ahead.\n\nAfterwards, write what you did, what you noticed, and what Sigrblót · Sumardagurinn fyrsti means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/sigrblot"},{"title":"Keep Midsummer (Miðsumar)","kind":"ritual","instructions":"Keep Midsummer (Miðsumar) with the coven, or on your own if the coven isn’t gathering.\n\nThe height of the sun’s power: bonfires, feasting and gathering, the season when the old assemblies (things) met.\n\nAfterwards, write what you did, what you noticed, and what Midsummer (Miðsumar) means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/midsummer"},{"title":"Keep Haustblót","kind":"ritual","instructions":"Keep Haustblót with the coven, or on your own if the coven isn’t gathering.\n\nAn autumn harvest blót kept by many modern heathens at the equinox, giving thanks to the gods and the land for the year’s harvest.\n\nAfterwards, write what you did, what you noticed, and what Haustblót means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/haustblot"},{"title":"Keep Winter Nights (Vetrnætur)","kind":"ritual","instructions":"Keep Winter Nights (Vetrnætur) with the coven, or on your own if the coven isn’t gathering.\n\nThe start of winter in the Icelandic year. The sagas tell of a blót “for a good year”, and it is a time to honor the álfar and dísir (Álfablót).\n\nAfterwards, write what you did, what you noticed, and what Winter Nights (Vetrnætur) means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/vetrnaetur"},{"title":"Keep Yule (Jól)","kind":"ritual","instructions":"Keep Yule (Jól) with the coven, or on your own if the coven isn’t gathering.\n\nThe great midwinter feast, traditionally kept for twelve nights: drinking to the gods and the ancestors for a good year and peace, and welcoming back the sun.\n\nAfterwards, write what you did, what you noticed, and what Yule (Jól) means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"norse/jol"},{"title":"Keep the monthly offerings","kind":"attend","instructions":"Make a simple offering to the gods, ancestors or landvættir once a month for twelve months.","times":12,"response":"none","checked_by":"mentor"},{"title":"The lore of the year","kind":"study","instructions":"Study the blóts of the year, the Winter Nights and Yule, the Eddas, and gifting for a gift. Write a short account in your own words.","times":1,"response":"text","checked_by":"mentor"},{"title":"Divination","kind":"practice","instructions":"Learn one form of divination your coven uses. Do a reading every week for three months and keep a record of what came true.","times":12,"response":"none","checked_by":"self"},{"title":"Relationship with the divine","kind":"reflection","instructions":"Keep a devotional practice to the gods, the ancestors and the landvættir (spirits of the land). At the half-year, write about the relationship as it’s growing.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Service","intro":"A coven is kept by its members. Give your craft and your time to the circle.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Write a page for the coven’s book","kind":"book","instructions":"Write a page for the coven’s Book of Shadows on something you’ve learned this year: a working, a recipe, a piece of lore. Send it for approval.","times":1,"response":"none","checked_by":"manager"},{"title":"Serve at coven rites","kind":"service","instructions":"Help prepare and clear away at two coven rites: setting the altar, bringing what’s needed, welcoming others.","times":2,"response":"none","checked_by":"mentor"},{"title":"Lead a part of a ritual","kind":"ritual","instructions":"Take one part of a coven ritual: calling a quarter, leading a chant, a reading, lighting the altar.","times":1,"response":"none","checked_by":"mentor"},{"title":"A service to the wider community","kind":"service","instructions":"Do something for people or land beyond the coven: a clean-up, a donation, help for someone in need. Write what you did.","times":1,"response":"text","checked_by":"mentor","optional":true}]},{"title":"Dedication and initiation","intro":"The end of the year and a day. You and the coven’s leaders decide together that you are ready.","min_days":0,"passed_by":"manager","tasks":[{"title":"A final conversation with your mentor","kind":"meeting","instructions":"Look back on the year with your mentor: what changed, what’s still to learn, and whether you are ready.","times":1,"response":"none","checked_by":"mentor"},{"title":"Write your oath","kind":"oath","instructions":"Write the oath you will take at your initiation, in your own words, and share it with the coven’s leaders.","times":1,"response":"text","checked_by":"manager"},{"title":"Initiation","kind":"ritual","instructions":"Your initiation into the coven, held by its leaders in the way of Heathen practice and the old Norse year.","times":1,"response":"none","checked_by":"manager"}]}]'::jsonb, 6)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('norse-training', 'training', 'norse', 'Norse & Heathen: foundations of the craft', 'Core training for members of a coven following Heathen practice and the old Norse year, at your own pace.', 'Eight modules of core skills for Heathen practice and the old Norse year, from energy work to writing a full ritual.

Members can take the modules alongside an initiation program or on their own. Mentors sign off most tasks; the last module is reviewed by the coven’s leaders.', '[{"title":"Energy and self","intro":"Feel, raise, direct and release energy, and keep yourself clear.","passed_by":"mentor","tasks":[{"title":"Grounding and centring","kind":"practice","instructions":"Practise grounding and centring until you can do it in under a minute. Log ten sessions.","times":10,"response":"none","checked_by":"self"},{"title":"Raising and directing energy","kind":"practice","instructions":"Raise energy by breath, chant or movement, direct it into an object, then release and ground what’s left. Describe what you felt.","times":1,"response":"text","checked_by":"mentor"},{"title":"Shielding","kind":"practice","instructions":"Learn a shielding method and use it every day for a week.","times":7,"response":"none","checked_by":"self"}]},{"title":"Sacred space","intro":"How to hallow a space (by fire, hammer or the coven’s own way) and hold a sumbel, and how to close it again cleanly.","passed_by":"mentor","tasks":[{"title":"Make and close sacred space","kind":"practice","instructions":"Learn the coven’s way to hallow a space (by fire, hammer or the coven’s own way) and hold a sumbel. Do it five times.","times":5,"response":"none","checked_by":"mentor"},{"title":"Purification","kind":"practice","instructions":"Learn the coven’s purification before ritual and use it before every working this month.","times":4,"response":"none","checked_by":"self"},{"title":"Write it down","kind":"book","instructions":"Write out the coven’s way of making sacred space as you now do it, for your own book.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Tools and the altar","intro":"The tools your coven uses, how to cleanse and consecrate them, and how to keep an altar.","passed_by":"mentor","tasks":[{"title":"Your altar","kind":"practice","instructions":"Keep a stalli (household altar) with a bowl for offerings and a place for the ancestors. Tend it weekly for a month.","times":4,"response":"none","checked_by":"self"},{"title":"Consecrate a tool","kind":"ritual","instructions":"Cleanse and consecrate one working tool. Write what you did and why.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Correspondences, herbs and stones","intro":"What things are for: plants, stones, colours, days and planetary hours.","passed_by":"mentor","tasks":[{"title":"Twelve plants","kind":"study","instructions":"Learn twelve plants your coven works with: their uses, cautions and lore. Keep a page for each.","times":12,"response":"none","checked_by":"self"},{"title":"Seven stones","kind":"study","instructions":"Learn seven stones and how to cleanse and charge them.","times":7,"response":"none","checked_by":"self"},{"title":"Days and hours","kind":"study","instructions":"Learn the planetary days and hours and when to use them. Plan one working by them.","times":1,"response":"text","checked_by":"mentor"},{"title":"Herbal safety","kind":"reflection","instructions":"Write which herbs and oils need care (pregnancy, pets, skin, ingestion) and how you’ll check before using something new.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Divination","intro":"Read for yourself and, later, for others.","passed_by":"mentor","tasks":[{"title":"Learn a system","kind":"study","instructions":"Choose a system (tarot, runes, ogham, oracle, scrying) and learn its basics.","times":1,"response":"text","checked_by":"mentor"},{"title":"Daily draws","kind":"practice","instructions":"Draw or cast daily for thirty days and note what each meant by evening.","times":30,"response":"none","checked_by":"self"},{"title":"Read for your mentor","kind":"practice","instructions":"Give your mentor a reading and talk through it together.","times":1,"response":"none","checked_by":"mentor"}]},{"title":"Gods, spirits and ancestors","intro":"Build relationship with the gods, the ancestors and the landvættir (spirits of the land).","passed_by":"mentor","tasks":[{"title":"A devotional practice","kind":"practice","instructions":"Keep a short daily devotion (an offering, a prayer, a candle) for a month.","times":30,"response":"none","checked_by":"self"},{"title":"Honour your ancestors","kind":"ritual","instructions":"Make a place for your ancestors (of blood, of spirit or of craft) and honour them. Write about who you honoured.","times":1,"response":"text","checked_by":"mentor"},{"title":"Discernment","kind":"reflection","instructions":"Write how you tell a real experience from wishful thinking, and when to ask for help.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"The year’s lore","intro":"Learn the blóts of the year, the Winter Nights and Yule, the Eddas, and gifting for a gift.","passed_by":"mentor","tasks":[{"title":"The lore of Þorrablót","kind":"study","instructions":"Learn the history, customs and meaning of Þorrablót: The midwinter feast at the start of the old Icelandic month of Þorri (Bóndadagur), honoring Þorri, the spirit of winter, with traditional foods and toasts. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/thorrablot"},{"title":"The lore of Dísablót","kind":"study","instructions":"Learn the history, customs and meaning of Dísablót: Offerings to the dísir, the ancestral mothers and guardian spirits of the family, in late winter, as at the Dísting held at Uppsala around the February full moon. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/disablot"},{"title":"The lore of Sigrblót · Sumardagurinn fyrsti","kind":"study","instructions":"Learn the history, customs and meaning of Sigrblót · Sumardagurinn fyrsti: The first day of summer in the Icelandic year. The sagas tell of a blót at summer’s start “for victory”, for the season of voyages and undertakings ahead. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/sigrblot"},{"title":"The lore of Midsummer (Miðsumar)","kind":"study","instructions":"Learn the history, customs and meaning of Midsummer (Miðsumar): The height of the sun’s power: bonfires, feasting and gathering, the season when the old assemblies (things) met. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/midsummer"},{"title":"The lore of Haustblót","kind":"study","instructions":"Learn the history, customs and meaning of Haustblót: An autumn harvest blót kept by many modern heathens at the equinox, giving thanks to the gods and the land for the year’s harvest. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/haustblot"},{"title":"The lore of Winter Nights (Vetrnætur)","kind":"study","instructions":"Learn the history, customs and meaning of Winter Nights (Vetrnætur): The start of winter in the Icelandic year. The sagas tell of a blót “for a good year”, and it is a time to honor the álfar and dísir (Álfablót). Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/vetrnaetur"},{"title":"The lore of Yule (Jól)","kind":"study","instructions":"Learn the history, customs and meaning of Yule (Jól): The great midwinter feast, traditionally kept for twelve nights: drinking to the gods and the ancestors for a good year and peace, and welcoming back the sun. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"norse/jol"}]},{"title":"Ritual craft","intro":"Bring it all together: write and lead a ritual of your own.","passed_by":"manager","tasks":[{"title":"Write a ritual","kind":"book","instructions":"Write a complete ritual for the coven: its purpose, sacred space, the working, the words and the closing.","times":1,"response":"text","checked_by":"manager"},{"title":"Lead it","kind":"ritual","instructions":"Lead your ritual for the coven or a few members, with your mentor present.","times":1,"response":"none","checked_by":"manager"},{"title":"Look back","kind":"reflection","instructions":"Write what went well, what you’d change, and what the training has given you.","times":1,"response":"text","checked_by":"mentor"}]}]'::jsonb, 7)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('hellenic-initiation', 'initiation', 'hellenic', 'Hellenic: a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every festival of Hellenic (ancient Greek) practice.', 'A traditional year and a day of study, practice and service before initiation, shaped around Hellenic (ancient Greek) practice.

Each stage builds on the one before. Some tasks you sign off yourself; your mentor signs off most; the coven’s leaders confirm the oath and the initiation itself.

Change anything to fit your coven: rename stages, add your own lore, set how long each stage takes, and choose who signs each task off.', '[{"title":"The threshold","intro":"Welcome. In this first stage you meet your mentor, read what the coven holds to, and set down why you seek Hellenic (ancient Greek) practice.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Meet your mentor","kind":"meeting","instructions":"Arrange a first conversation with your mentor. Talk about what drew you here, what you hope to learn, and how you’ll keep in touch through the year.","times":1,"response":"none","checked_by":"mentor"},{"title":"Read the coven’s creed, rules and agreements","kind":"study","instructions":"Read every page the coven has written, and ask your mentor about anything that isn’t clear.","times":1,"response":"none","checked_by":"self"},{"title":"Why I seek this path","kind":"reflection","instructions":"Write a page on why you seek Hellenic (ancient Greek) practice, what you already practise, and what you hope the year will open.","times":1,"response":"text","checked_by":"mentor"},{"title":"Begin a magical diary","kind":"practice","instructions":"Start a diary you’ll keep all year: dreams, workings, moods, the weather, the moon. Write in it at least once a week.","times":1,"response":"none","checked_by":"self"},{"title":"Set up your personal altar","kind":"practice","instructions":"Make a household shrine with a flame for Hestia, a libation bowl and khernips at home. Describe it, and why you chose what’s on it.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Foundations","intro":"The skills everything else rests on: steadying yourself, keeping your space clean and warded, and making sacred space well.","min_days":90,"passed_by":"mentor","tasks":[{"title":"Ground and centre daily","kind":"practice","instructions":"Ground and centre every day for thirty days: breath, roots, a calm centre. Log each day you do it.","times":30,"response":"none","checked_by":"self","minutes":10},{"title":"Cleanse and ward your home","kind":"practice","instructions":"Cleanse your home and set wards in the coven’s way. Write what you used and how the space felt before and after.","times":1,"response":"text","checked_by":"mentor"},{"title":"Make sacred space","kind":"practice","instructions":"Learn to purify with khernips (lustral water) before ritual and pour libations. Do it three times, then show your mentor.","times":3,"response":"none","checked_by":"mentor"},{"title":"The elements and the directions","kind":"study","instructions":"Study the elements (or the coven’s equivalent) and their correspondences: directions, colours, tools, times. Write a page for each.","times":1,"response":"text","checked_by":"mentor"},{"title":"Ethics and consent","kind":"reflection","instructions":"Write on the ethics of magic: harm, consent, working for others, and what you will and won’t do. Talk it through with your mentor.","times":1,"response":"text","checked_by":"mentor"},{"title":"Meditation and trance","kind":"practice","instructions":"Practise meditation or light trance twelve times, building from ten minutes to thirty.","times":12,"response":"none","checked_by":"self"}]},{"title":"Turning the year","intro":"A year and a day of Hellenic (ancient Greek) practice. Keep each festival as it comes and learn the Attic festival year, Hesiod and the Homeric Hymns, and the virtues of kharis and xenia. This stage lasts at least a year and a day.","min_days":366,"passed_by":"mentor","tasks":[{"title":"Keep Kronia","kind":"ritual","instructions":"Keep Kronia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Kronos, when masters and the enslaved feasted together in memory of the Golden Age.\n\nAfterwards, write what you did, what you noticed, and what Kronia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/kronia"},{"title":"Keep Panathenaia","kind":"ritual","instructions":"Keep Panathenaia with the coven, or on your own if the coven isn’t gathering.\n\nAthena’s birthday festival: a great procession brings her statue a newly woven robe (peplos), with games and sacrifice.\n\nAfterwards, write what you did, what you noticed, and what Panathenaia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/panathenaia"},{"title":"Keep Eleusinian Mysteries","kind":"ritual","instructions":"Keep Eleusinian Mysteries with the coven, or on your own if the coven isn’t gathering.\n\nThe Greater Mysteries of Demeter and Persephone at Eleusis, the most revered initiation of the ancient world, about loss, return and the promise of life after death.\n\nAfterwards, write what you did, what you noticed, and what Eleusinian Mysteries means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/eleusinia"},{"title":"Keep Pyanepsia","kind":"ritual","instructions":"Keep Pyanepsia with the coven, or on your own if the coven isn’t gathering.\n\nApollo’s harvest festival: a pot of mixed beans, and the eiresione, an olive branch hung with wool and fruits, carried home for blessing.\n\nAfterwards, write what you did, what you noticed, and what Pyanepsia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/pyanepsia"},{"title":"Keep Thesmophoria","kind":"ritual","instructions":"Keep Thesmophoria with the coven, or on your own if the coven isn’t gathering.\n\nThe women’s festival of Demeter Thesmophoros and Persephone, for the fertility of the fields and of families.\n\nAfterwards, write what you did, what you noticed, and what Thesmophoria means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/thesmophoria"},{"title":"Keep Haloa","kind":"ritual","instructions":"Keep Haloa with the coven, or on your own if the coven isn’t gathering.\n\nA winter festival of Demeter, Kore and Dionysus at the threshing floor, kept by women with feasting and joking.\n\nAfterwards, write what you did, what you noticed, and what Haloa means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/haloa"},{"title":"Keep Lenaia","kind":"ritual","instructions":"Keep Lenaia with the coven, or on your own if the coven isn’t gathering.\n\nThe winter festival of Dionysus Lenaios, with dramatic contests of comedy and tragedy.\n\nAfterwards, write what you did, what you noticed, and what Lenaia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/lenaia"},{"title":"Keep Anthesteria","kind":"ritual","instructions":"Keep Anthesteria with the coven, or on your own if the coven isn’t gathering.\n\nDionysus’s festival of flowers and the new wine. On its last day the spirits of the dead walk, and are sent away at its close.\n\nAfterwards, write what you did, what you noticed, and what Anthesteria means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/anthesteria"},{"title":"Keep City Dionysia","kind":"ritual","instructions":"Keep City Dionysia with the coven, or on your own if the coven isn’t gathering.\n\nThe Great Dionysia, Athens’ spring festival of Dionysus, where the great tragedies and comedies were first performed.\n\nAfterwards, write what you did, what you noticed, and what City Dionysia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/dionysia"},{"title":"Keep Mounichia","kind":"ritual","instructions":"Keep Mounichia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Artemis Mounichia, with round cakes ringed by small torches (amphiphontes), shining like the full moon.\n\nAfterwards, write what you did, what you noticed, and what Mounichia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/mounichia"},{"title":"Keep Thargelia","kind":"ritual","instructions":"Keep Thargelia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Apollo and Artemis on their birthdays, with first fruits of the harvest and the purification of the city.\n\nAfterwards, write what you did, what you noticed, and what Thargelia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/thargelia"},{"title":"Keep Plynteria","kind":"ritual","instructions":"Keep Plynteria with the coven, or on your own if the coven isn’t gathering.\n\nAthena’s ancient statue is taken to be washed and her robes cleaned; a solemn day of cleansing and renewal.\n\nAfterwards, write what you did, what you noticed, and what Plynteria means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/plynteria"},{"title":"Keep Skira","kind":"ritual","instructions":"Keep Skira with the coven, or on your own if the coven isn’t gathering.\n\nA midsummer women’s festival of Demeter and Persephone, ahead of the threshing.\n\nAfterwards, write what you did, what you noticed, and what Skira means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"hellenic/skira"},{"title":"Keep the monthly days","kind":"attend","instructions":"Keep the Noumenia (the new month) and Hekate’s Deipnon for twelve months: cleanse the house, set out the supper, and greet the new month.","times":12,"response":"none","checked_by":"mentor"},{"title":"The lore of the year","kind":"study","instructions":"Study the Attic festival year, Hesiod and the Homeric Hymns, and the virtues of kharis and xenia. Write a short account in your own words.","times":1,"response":"text","checked_by":"mentor"},{"title":"Divination","kind":"practice","instructions":"Learn one form of divination your coven uses. Do a reading every week for three months and keep a record of what came true.","times":12,"response":"none","checked_by":"self"},{"title":"Relationship with the divine","kind":"reflection","instructions":"Keep a devotional practice to the theoi, the household gods (Hestia first) and the heroes. At the half-year, write about the relationship as it’s growing.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Service","intro":"A coven is kept by its members. Give your craft and your time to the circle.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Write a page for the coven’s book","kind":"book","instructions":"Write a page for the coven’s Book of Shadows on something you’ve learned this year: a working, a recipe, a piece of lore. Send it for approval.","times":1,"response":"none","checked_by":"manager"},{"title":"Serve at coven rites","kind":"service","instructions":"Help prepare and clear away at two coven rites: setting the altar, bringing what’s needed, welcoming others.","times":2,"response":"none","checked_by":"mentor"},{"title":"Lead a part of a ritual","kind":"ritual","instructions":"Take one part of a coven ritual: calling a quarter, leading a chant, a reading, lighting the altar.","times":1,"response":"none","checked_by":"mentor"},{"title":"A service to the wider community","kind":"service","instructions":"Do something for people or land beyond the coven: a clean-up, a donation, help for someone in need. Write what you did.","times":1,"response":"text","checked_by":"mentor","optional":true}]},{"title":"Dedication and initiation","intro":"The end of the year and a day. You and the coven’s leaders decide together that you are ready.","min_days":0,"passed_by":"manager","tasks":[{"title":"A final conversation with your mentor","kind":"meeting","instructions":"Look back on the year with your mentor: what changed, what’s still to learn, and whether you are ready.","times":1,"response":"none","checked_by":"mentor"},{"title":"Write your oath","kind":"oath","instructions":"Write the oath you will take at your initiation, in your own words, and share it with the coven’s leaders.","times":1,"response":"text","checked_by":"manager"},{"title":"Initiation","kind":"ritual","instructions":"Your initiation into the coven, held by its leaders in the way of Hellenic (ancient Greek) practice.","times":1,"response":"none","checked_by":"manager"}]}]'::jsonb, 8)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('hellenic-training', 'training', 'hellenic', 'Hellenic: foundations of the craft', 'Core training for members of a coven following Hellenic (ancient Greek) practice, at your own pace.', 'Eight modules of core skills for Hellenic (ancient Greek) practice, from energy work to writing a full ritual.

Members can take the modules alongside an initiation program or on their own. Mentors sign off most tasks; the last module is reviewed by the coven’s leaders.', '[{"title":"Energy and self","intro":"Feel, raise, direct and release energy, and keep yourself clear.","passed_by":"mentor","tasks":[{"title":"Grounding and centring","kind":"practice","instructions":"Practise grounding and centring until you can do it in under a minute. Log ten sessions.","times":10,"response":"none","checked_by":"self"},{"title":"Raising and directing energy","kind":"practice","instructions":"Raise energy by breath, chant or movement, direct it into an object, then release and ground what’s left. Describe what you felt.","times":1,"response":"text","checked_by":"mentor"},{"title":"Shielding","kind":"practice","instructions":"Learn a shielding method and use it every day for a week.","times":7,"response":"none","checked_by":"self"}]},{"title":"Sacred space","intro":"How to purify with khernips (lustral water) before ritual and pour libations, and how to close it again cleanly.","passed_by":"mentor","tasks":[{"title":"Make and close sacred space","kind":"practice","instructions":"Learn the coven’s way to purify with khernips (lustral water) before ritual and pour libations. Do it five times.","times":5,"response":"none","checked_by":"mentor"},{"title":"Purification","kind":"practice","instructions":"Learn the coven’s purification before ritual and use it before every working this month.","times":4,"response":"none","checked_by":"self"},{"title":"Write it down","kind":"book","instructions":"Write out the coven’s way of making sacred space as you now do it, for your own book.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Tools and the altar","intro":"The tools your coven uses, how to cleanse and consecrate them, and how to keep an altar.","passed_by":"mentor","tasks":[{"title":"Your altar","kind":"practice","instructions":"Keep a household shrine with a flame for Hestia, a libation bowl and khernips. Tend it weekly for a month.","times":4,"response":"none","checked_by":"self"},{"title":"Consecrate a tool","kind":"ritual","instructions":"Cleanse and consecrate one working tool. Write what you did and why.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Correspondences, herbs and stones","intro":"What things are for: plants, stones, colours, days and planetary hours.","passed_by":"mentor","tasks":[{"title":"Twelve plants","kind":"study","instructions":"Learn twelve plants your coven works with: their uses, cautions and lore. Keep a page for each.","times":12,"response":"none","checked_by":"self"},{"title":"Seven stones","kind":"study","instructions":"Learn seven stones and how to cleanse and charge them.","times":7,"response":"none","checked_by":"self"},{"title":"Days and hours","kind":"study","instructions":"Learn the planetary days and hours and when to use them. Plan one working by them.","times":1,"response":"text","checked_by":"mentor"},{"title":"Herbal safety","kind":"reflection","instructions":"Write which herbs and oils need care (pregnancy, pets, skin, ingestion) and how you’ll check before using something new.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Divination","intro":"Read for yourself and, later, for others.","passed_by":"mentor","tasks":[{"title":"Learn a system","kind":"study","instructions":"Choose a system (tarot, runes, ogham, oracle, scrying) and learn its basics.","times":1,"response":"text","checked_by":"mentor"},{"title":"Daily draws","kind":"practice","instructions":"Draw or cast daily for thirty days and note what each meant by evening.","times":30,"response":"none","checked_by":"self"},{"title":"Read for your mentor","kind":"practice","instructions":"Give your mentor a reading and talk through it together.","times":1,"response":"none","checked_by":"mentor"}]},{"title":"Gods, spirits and ancestors","intro":"Build relationship with the theoi, the household gods (Hestia first) and the heroes.","passed_by":"mentor","tasks":[{"title":"A devotional practice","kind":"practice","instructions":"Keep a short daily devotion (an offering, a prayer, a candle) for a month.","times":30,"response":"none","checked_by":"self"},{"title":"Honour your ancestors","kind":"ritual","instructions":"Make a place for your ancestors (of blood, of spirit or of craft) and honour them. Write about who you honoured.","times":1,"response":"text","checked_by":"mentor"},{"title":"Discernment","kind":"reflection","instructions":"Write how you tell a real experience from wishful thinking, and when to ask for help.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"The year’s lore","intro":"Learn the Attic festival year, Hesiod and the Homeric Hymns, and the virtues of kharis and xenia.","passed_by":"mentor","tasks":[{"title":"The lore of Kronia","kind":"study","instructions":"Learn the history, customs and meaning of Kronia: Festival of Kronos, when masters and the enslaved feasted together in memory of the Golden Age. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/kronia"},{"title":"The lore of Panathenaia","kind":"study","instructions":"Learn the history, customs and meaning of Panathenaia: Athena’s birthday festival: a great procession brings her statue a newly woven robe (peplos), with games and sacrifice. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/panathenaia"},{"title":"The lore of Eleusinian Mysteries","kind":"study","instructions":"Learn the history, customs and meaning of Eleusinian Mysteries: The Greater Mysteries of Demeter and Persephone at Eleusis, the most revered initiation of the ancient world, about loss, return and the promise of life after death. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/eleusinia"},{"title":"The lore of Pyanepsia","kind":"study","instructions":"Learn the history, customs and meaning of Pyanepsia: Apollo’s harvest festival: a pot of mixed beans, and the eiresione, an olive branch hung with wool and fruits, carried home for blessing. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/pyanepsia"},{"title":"The lore of Thesmophoria","kind":"study","instructions":"Learn the history, customs and meaning of Thesmophoria: The women’s festival of Demeter Thesmophoros and Persephone, for the fertility of the fields and of families. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/thesmophoria"},{"title":"The lore of Haloa","kind":"study","instructions":"Learn the history, customs and meaning of Haloa: A winter festival of Demeter, Kore and Dionysus at the threshing floor, kept by women with feasting and joking. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/haloa"},{"title":"The lore of Lenaia","kind":"study","instructions":"Learn the history, customs and meaning of Lenaia: The winter festival of Dionysus Lenaios, with dramatic contests of comedy and tragedy. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/lenaia"},{"title":"The lore of Anthesteria","kind":"study","instructions":"Learn the history, customs and meaning of Anthesteria: Dionysus’s festival of flowers and the new wine. On its last day the spirits of the dead walk, and are sent away at its close. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/anthesteria"},{"title":"The lore of City Dionysia","kind":"study","instructions":"Learn the history, customs and meaning of City Dionysia: The Great Dionysia, Athens’ spring festival of Dionysus, where the great tragedies and comedies were first performed. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/dionysia"},{"title":"The lore of Mounichia","kind":"study","instructions":"Learn the history, customs and meaning of Mounichia: Festival of Artemis Mounichia, with round cakes ringed by small torches (amphiphontes), shining like the full moon. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/mounichia"},{"title":"The lore of Thargelia","kind":"study","instructions":"Learn the history, customs and meaning of Thargelia: Festival of Apollo and Artemis on their birthdays, with first fruits of the harvest and the purification of the city. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/thargelia"},{"title":"The lore of Plynteria","kind":"study","instructions":"Learn the history, customs and meaning of Plynteria: Athena’s ancient statue is taken to be washed and her robes cleaned; a solemn day of cleansing and renewal. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/plynteria"},{"title":"The lore of Skira","kind":"study","instructions":"Learn the history, customs and meaning of Skira: A midsummer women’s festival of Demeter and Persephone, ahead of the threshing. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"hellenic/skira"}]},{"title":"Ritual craft","intro":"Bring it all together: write and lead a ritual of your own.","passed_by":"manager","tasks":[{"title":"Write a ritual","kind":"book","instructions":"Write a complete ritual for the coven: its purpose, sacred space, the working, the words and the closing.","times":1,"response":"text","checked_by":"manager"},{"title":"Lead it","kind":"ritual","instructions":"Lead your ritual for the coven or a few members, with your mentor present.","times":1,"response":"none","checked_by":"manager"},{"title":"Look back","kind":"reflection","instructions":"Write what went well, what you’d change, and what the training has given you.","times":1,"response":"text","checked_by":"mentor"}]}]'::jsonb, 9)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('roman-initiation', 'initiation', 'roman', 'Roman: a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every feast of Roman religio and household practice.', 'A traditional year and a day of study, practice and service before initiation, shaped around Roman religio and household practice.

Each stage builds on the one before. Some tasks you sign off yourself; your mentor signs off most; the coven’s leaders confirm the oath and the initiation itself.

Change anything to fit your coven: rename stages, add your own lore, set how long each stage takes, and choose who signs each task off.', '[{"title":"The threshold","intro":"Welcome. In this first stage you meet your mentor, read what the coven holds to, and set down why you seek Roman religio and household practice.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Meet your mentor","kind":"meeting","instructions":"Arrange a first conversation with your mentor. Talk about what drew you here, what you hope to learn, and how you’ll keep in touch through the year.","times":1,"response":"none","checked_by":"mentor"},{"title":"Read the coven’s creed, rules and agreements","kind":"study","instructions":"Read every page the coven has written, and ask your mentor about anything that isn’t clear.","times":1,"response":"none","checked_by":"self"},{"title":"Why I seek this path","kind":"reflection","instructions":"Write a page on why you seek Roman religio and household practice, what you already practise, and what you hope the year will open.","times":1,"response":"text","checked_by":"mentor"},{"title":"Begin a magical diary","kind":"practice","instructions":"Start a diary you’ll keep all year: dreams, workings, moods, the weather, the moon. Write in it at least once a week.","times":1,"response":"none","checked_by":"self"},{"title":"Set up your personal altar","kind":"practice","instructions":"Make a lararium (household shrine) for the Lares, the Penates and the genius of the house at home. Describe it, and why you chose what’s on it.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Foundations","intro":"The skills everything else rests on: steadying yourself, keeping your space clean and warded, and making sacred space well.","min_days":90,"passed_by":"mentor","tasks":[{"title":"Ground and centre daily","kind":"practice","instructions":"Ground and centre every day for thirty days: breath, roots, a calm centre. Log each day you do it.","times":30,"response":"none","checked_by":"self","minutes":10},{"title":"Cleanse and ward your home","kind":"practice","instructions":"Cleanse your home and set wards in the coven’s way. Write what you used and how the space felt before and after.","times":1,"response":"text","checked_by":"mentor"},{"title":"Make sacred space","kind":"practice","instructions":"Learn to wash, veil and pray with the proper words, and offer incense, wine and grain. Do it three times, then show your mentor.","times":3,"response":"none","checked_by":"mentor"},{"title":"The elements and the directions","kind":"study","instructions":"Study the elements (or the coven’s equivalent) and their correspondences: directions, colours, tools, times. Write a page for each.","times":1,"response":"text","checked_by":"mentor"},{"title":"Ethics and consent","kind":"reflection","instructions":"Write on the ethics of magic: harm, consent, working for others, and what you will and won’t do. Talk it through with your mentor.","times":1,"response":"text","checked_by":"mentor"},{"title":"Meditation and trance","kind":"practice","instructions":"Practise meditation or light trance twelve times, building from ten minutes to thirty.","times":12,"response":"none","checked_by":"self"}]},{"title":"Turning the year","intro":"A year and a day of Roman religio and household practice. Keep each feast as it comes and learn the Roman year, the household cult, pietas, and the do ut des of offering. This stage lasts at least a year and a day.","min_days":366,"passed_by":"mentor","tasks":[{"title":"Keep Parentalia","kind":"ritual","instructions":"Keep Parentalia with the coven, or on your own if the coven isn’t gathering.\n\nNine days honoring the family’s ancestors, with offerings of flowers, bread and wine at their tombs.\n\nAfterwards, write what you did, what you noticed, and what Parentalia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/parentalia"},{"title":"Keep Lupercalia","kind":"ritual","instructions":"Keep Lupercalia with the coven, or on your own if the coven isn’t gathering.\n\nAn ancient festival of purification and fertility, honoring Faunus and the she-wolf who nursed Romulus and Remus.\n\nAfterwards, write what you did, what you noticed, and what Lupercalia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/lupercalia"},{"title":"Keep Matronalia","kind":"ritual","instructions":"Keep Matronalia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Juno Lucina, goddess of childbirth; mothers and wives are honored and given gifts.\n\nAfterwards, write what you did, what you noticed, and what Matronalia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/matronalia"},{"title":"Keep Floralia","kind":"ritual","instructions":"Keep Floralia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Flora, goddess of flowers and springtime, with games, theatre and bright clothing.\n\nAfterwards, write what you did, what you noticed, and what Floralia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/floralia"},{"title":"Keep Lemuria","kind":"ritual","instructions":"Keep Lemuria with the coven, or on your own if the coven isn’t gathering.\n\nRites to appease the restless dead (lemures), who are sent from the house at midnight with black beans.\n\nAfterwards, write what you did, what you noticed, and what Lemuria means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/lemuria"},{"title":"Keep Vestalia","kind":"ritual","instructions":"Keep Vestalia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Vesta, goddess of the hearth, when her temple was opened to the women of Rome.\n\nAfterwards, write what you did, what you noticed, and what Vestalia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/vestalia"},{"title":"Keep Neptunalia","kind":"ritual","instructions":"Keep Neptunalia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Neptune in the summer heat, with shelters made of leafy branches.\n\nAfterwards, write what you did, what you noticed, and what Neptunalia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/neptunalia"},{"title":"Keep Saturnalia","kind":"ritual","instructions":"Keep Saturnalia with the coven, or on your own if the coven isn’t gathering.\n\nFestival of Saturn: feasting, candles and gift-giving, when ordinary rules were set aside and roles turned upside down.\n\nAfterwards, write what you did, what you noticed, and what Saturnalia means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/saturnalia"},{"title":"Keep Dies Natalis Solis Invicti","kind":"ritual","instructions":"Keep Dies Natalis Solis Invicti with the coven, or on your own if the coven isn’t gathering.\n\nThe birthday of the Unconquered Sun, celebrating the sun’s return after the winter solstice.\n\nAfterwards, write what you did, what you noticed, and what Dies Natalis Solis Invicti means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"roman/sol_invictus"},{"title":"Keep the Kalends","kind":"attend","instructions":"Make an offering at the lararium on the Kalends (first day) of each month for twelve months.","times":12,"response":"none","checked_by":"mentor"},{"title":"The lore of the year","kind":"study","instructions":"Study the Roman year, the household cult, pietas, and the do ut des of offering. Write a short account in your own words.","times":1,"response":"text","checked_by":"mentor"},{"title":"Divination","kind":"practice","instructions":"Learn one form of divination your coven uses. Do a reading every week for three months and keep a record of what came true.","times":12,"response":"none","checked_by":"self"},{"title":"Relationship with the divine","kind":"reflection","instructions":"Keep a devotional practice to the di immortales, the Lares and Penates, and the family’s ancestors. At the half-year, write about the relationship as it’s growing.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Service","intro":"A coven is kept by its members. Give your craft and your time to the circle.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Write a page for the coven’s book","kind":"book","instructions":"Write a page for the coven’s Book of Shadows on something you’ve learned this year: a working, a recipe, a piece of lore. Send it for approval.","times":1,"response":"none","checked_by":"manager"},{"title":"Serve at coven rites","kind":"service","instructions":"Help prepare and clear away at two coven rites: setting the altar, bringing what’s needed, welcoming others.","times":2,"response":"none","checked_by":"mentor"},{"title":"Lead a part of a ritual","kind":"ritual","instructions":"Take one part of a coven ritual: calling a quarter, leading a chant, a reading, lighting the altar.","times":1,"response":"none","checked_by":"mentor"},{"title":"A service to the wider community","kind":"service","instructions":"Do something for people or land beyond the coven: a clean-up, a donation, help for someone in need. Write what you did.","times":1,"response":"text","checked_by":"mentor","optional":true}]},{"title":"Dedication and initiation","intro":"The end of the year and a day. You and the coven’s leaders decide together that you are ready.","min_days":0,"passed_by":"manager","tasks":[{"title":"A final conversation with your mentor","kind":"meeting","instructions":"Look back on the year with your mentor: what changed, what’s still to learn, and whether you are ready.","times":1,"response":"none","checked_by":"mentor"},{"title":"Write your oath","kind":"oath","instructions":"Write the oath you will take at your initiation, in your own words, and share it with the coven’s leaders.","times":1,"response":"text","checked_by":"manager"},{"title":"Initiation","kind":"ritual","instructions":"Your initiation into the coven, held by its leaders in the way of Roman religio and household practice.","times":1,"response":"none","checked_by":"manager"}]}]'::jsonb, 10)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
