insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('roman-training', 'training', 'roman', 'Roman: foundations of the craft', 'Core training for members of a coven following Roman religio and household practice, at your own pace.', 'Eight modules of core skills for Roman religio and household practice, from energy work to writing a full ritual.

Members can take the modules alongside an initiation program or on their own. Mentors sign off most tasks; the last module is reviewed by the coven’s leaders.', '[{"title":"Energy and self","intro":"Feel, raise, direct and release energy, and keep yourself clear.","passed_by":"mentor","tasks":[{"title":"Grounding and centring","kind":"practice","instructions":"Practise grounding and centring until you can do it in under a minute. Log ten sessions.","times":10,"response":"none","checked_by":"self"},{"title":"Raising and directing energy","kind":"practice","instructions":"Raise energy by breath, chant or movement, direct it into an object, then release and ground what’s left. Describe what you felt.","times":1,"response":"text","checked_by":"mentor"},{"title":"Shielding","kind":"practice","instructions":"Learn a shielding method and use it every day for a week.","times":7,"response":"none","checked_by":"self"}]},{"title":"Sacred space","intro":"How to wash, veil and pray with the proper words, and offer incense, wine and grain, and how to close it again cleanly.","passed_by":"mentor","tasks":[{"title":"Make and close sacred space","kind":"practice","instructions":"Learn the coven’s way to wash, veil and pray with the proper words, and offer incense, wine and grain. Do it five times.","times":5,"response":"none","checked_by":"mentor"},{"title":"Purification","kind":"practice","instructions":"Learn the coven’s purification before ritual and use it before every working this month.","times":4,"response":"none","checked_by":"self"},{"title":"Write it down","kind":"book","instructions":"Write out the coven’s way of making sacred space as you now do it, for your own book.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Tools and the altar","intro":"The tools your coven uses, how to cleanse and consecrate them, and how to keep an altar.","passed_by":"mentor","tasks":[{"title":"Your altar","kind":"practice","instructions":"Keep a lararium (household shrine) for the Lares, the Penates and the genius of the house. Tend it weekly for a month.","times":4,"response":"none","checked_by":"self"},{"title":"Consecrate a tool","kind":"ritual","instructions":"Cleanse and consecrate one working tool. Write what you did and why.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Correspondences, herbs and stones","intro":"What things are for: plants, stones, colours, days and planetary hours.","passed_by":"mentor","tasks":[{"title":"Twelve plants","kind":"study","instructions":"Learn twelve plants your coven works with: their uses, cautions and lore. Keep a page for each.","times":12,"response":"none","checked_by":"self"},{"title":"Seven stones","kind":"study","instructions":"Learn seven stones and how to cleanse and charge them.","times":7,"response":"none","checked_by":"self"},{"title":"Days and hours","kind":"study","instructions":"Learn the planetary days and hours and when to use them. Plan one working by them.","times":1,"response":"text","checked_by":"mentor"},{"title":"Herbal safety","kind":"reflection","instructions":"Write which herbs and oils need care (pregnancy, pets, skin, ingestion) and how you’ll check before using something new.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Divination","intro":"Read for yourself and, later, for others.","passed_by":"mentor","tasks":[{"title":"Learn a system","kind":"study","instructions":"Choose a system (tarot, runes, ogham, oracle, scrying) and learn its basics.","times":1,"response":"text","checked_by":"mentor"},{"title":"Daily draws","kind":"practice","instructions":"Draw or cast daily for thirty days and note what each meant by evening.","times":30,"response":"none","checked_by":"self"},{"title":"Read for your mentor","kind":"practice","instructions":"Give your mentor a reading and talk through it together.","times":1,"response":"none","checked_by":"mentor"}]},{"title":"Gods, spirits and ancestors","intro":"Build relationship with the di immortales, the Lares and Penates, and the family’s ancestors.","passed_by":"mentor","tasks":[{"title":"A devotional practice","kind":"practice","instructions":"Keep a short daily devotion (an offering, a prayer, a candle) for a month.","times":30,"response":"none","checked_by":"self"},{"title":"Honour your ancestors","kind":"ritual","instructions":"Make a place for your ancestors (of blood, of spirit or of craft) and honour them. Write about who you honoured.","times":1,"response":"text","checked_by":"mentor"},{"title":"Discernment","kind":"reflection","instructions":"Write how you tell a real experience from wishful thinking, and when to ask for help.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"The year’s lore","intro":"Learn the Roman year, the household cult, pietas, and the do ut des of offering.","passed_by":"mentor","tasks":[{"title":"The lore of Parentalia","kind":"study","instructions":"Learn the history, customs and meaning of Parentalia: Nine days honoring the family’s ancestors, with offerings of flowers, bread and wine at their tombs. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/parentalia"},{"title":"The lore of Lupercalia","kind":"study","instructions":"Learn the history, customs and meaning of Lupercalia: An ancient festival of purification and fertility, honoring Faunus and the she-wolf who nursed Romulus and Remus. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/lupercalia"},{"title":"The lore of Matronalia","kind":"study","instructions":"Learn the history, customs and meaning of Matronalia: Festival of Juno Lucina, goddess of childbirth; mothers and wives are honored and given gifts. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/matronalia"},{"title":"The lore of Floralia","kind":"study","instructions":"Learn the history, customs and meaning of Floralia: Festival of Flora, goddess of flowers and springtime, with games, theatre and bright clothing. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/floralia"},{"title":"The lore of Lemuria","kind":"study","instructions":"Learn the history, customs and meaning of Lemuria: Rites to appease the restless dead (lemures), who are sent from the house at midnight with black beans. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/lemuria"},{"title":"The lore of Vestalia","kind":"study","instructions":"Learn the history, customs and meaning of Vestalia: Festival of Vesta, goddess of the hearth, when her temple was opened to the women of Rome. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/vestalia"},{"title":"The lore of Neptunalia","kind":"study","instructions":"Learn the history, customs and meaning of Neptunalia: Festival of Neptune in the summer heat, with shelters made of leafy branches. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/neptunalia"},{"title":"The lore of Saturnalia","kind":"study","instructions":"Learn the history, customs and meaning of Saturnalia: Festival of Saturn: feasting, candles and gift-giving, when ordinary rules were set aside and roles turned upside down. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/saturnalia"},{"title":"The lore of Dies Natalis Solis Invicti","kind":"study","instructions":"Learn the history, customs and meaning of Dies Natalis Solis Invicti: The birthday of the Unconquered Sun, celebrating the sun’s return after the winter solstice. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"roman/sol_invictus"}]},{"title":"Ritual craft","intro":"Bring it all together: write and lead a ritual of your own.","passed_by":"manager","tasks":[{"title":"Write a ritual","kind":"book","instructions":"Write a complete ritual for the coven: its purpose, sacred space, the working, the words and the closing.","times":1,"response":"text","checked_by":"manager"},{"title":"Lead it","kind":"ritual","instructions":"Lead your ritual for the coven or a few members, with your mentor present.","times":1,"response":"none","checked_by":"manager"},{"title":"Look back","kind":"reflection","instructions":"Write what went well, what you’d change, and what the training has given you.","times":1,"response":"text","checked_by":"mentor"}]}]'::jsonb, 11)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('slavic-initiation', 'initiation', 'slavic', 'Slavic: a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every feast of Slavic folk practice.', 'A traditional year and a day of study, practice and service before initiation, shaped around Slavic folk practice.

Each stage builds on the one before. Some tasks you sign off yourself; your mentor signs off most; the coven’s leaders confirm the oath and the initiation itself.

Change anything to fit your coven: rename stages, add your own lore, set how long each stage takes, and choose who signs each task off.', '[{"title":"The threshold","intro":"Welcome. In this first stage you meet your mentor, read what the coven holds to, and set down why you seek Slavic folk practice.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Meet your mentor","kind":"meeting","instructions":"Arrange a first conversation with your mentor. Talk about what drew you here, what you hope to learn, and how you’ll keep in touch through the year.","times":1,"response":"none","checked_by":"mentor"},{"title":"Read the coven’s creed, rules and agreements","kind":"study","instructions":"Read every page the coven has written, and ask your mentor about anything that isn’t clear.","times":1,"response":"none","checked_by":"self"},{"title":"Why I seek this path","kind":"reflection","instructions":"Write a page on why you seek Slavic folk practice, what you already practise, and what you hope the year will open.","times":1,"response":"text","checked_by":"mentor"},{"title":"Begin a magical diary","kind":"practice","instructions":"Start a diary you’ll keep all year: dreams, workings, moods, the weather, the moon. Write in it at least once a week.","times":1,"response":"none","checked_by":"self"},{"title":"Set up your personal altar","kind":"practice","instructions":"Make a red corner or hearth shrine with bread, salt and a candle for the ancestors at home. Describe it, and why you chose what’s on it.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Foundations","intro":"The skills everything else rests on: steadying yourself, keeping your space clean and warded, and making sacred space well.","min_days":90,"passed_by":"mentor","tasks":[{"title":"Ground and centre daily","kind":"practice","instructions":"Ground and centre every day for thirty days: breath, roots, a calm centre. Log each day you do it.","times":30,"response":"none","checked_by":"self","minutes":10},{"title":"Cleanse and ward your home","kind":"practice","instructions":"Cleanse your home and set wards in the coven’s way. Write what you used and how the space felt before and after.","times":1,"response":"text","checked_by":"mentor"},{"title":"Make sacred space","kind":"practice","instructions":"Learn to bless the space by fire and water, with bread and salt. Do it three times, then show your mentor.","times":3,"response":"none","checked_by":"mentor"},{"title":"The elements and the directions","kind":"study","instructions":"Study the elements (or the coven’s equivalent) and their correspondences: directions, colours, tools, times. Write a page for each.","times":1,"response":"text","checked_by":"mentor"},{"title":"Ethics and consent","kind":"reflection","instructions":"Write on the ethics of magic: harm, consent, working for others, and what you will and won’t do. Talk it through with your mentor.","times":1,"response":"text","checked_by":"mentor"},{"title":"Meditation and trance","kind":"practice","instructions":"Practise meditation or light trance twelve times, building from ten minutes to thirty.","times":12,"response":"none","checked_by":"self"}]},{"title":"Turning the year","intro":"A year and a day of Slavic folk practice. Keep each feast as it comes and learn the turning year from Koliada to Kupala and Dziady, folk songs and the care of the house spirit. This stage lasts at least a year and a day.","min_days":366,"passed_by":"mentor","tasks":[{"title":"Keep Drowning of Marzanna","kind":"ritual","instructions":"Keep Drowning of Marzanna with the coven, or on your own if the coven isn’t gathering.\n\nAn effigy of Marzanna (Morana), the figure of winter and death, is burned or drowned to send winter away and welcome spring. Traditionally on the fourth Sunday of Lent in Poland and Czechia; many now keep it on the first day of spring or at the equinox. She is first named by the 15th-century chronicler Jan Długosz, who likened her to Ceres; whether she was ever a goddess is debated.\n\nAfterwards, write what you did, what you noticed, and what Drowning of Marzanna means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"slavic/marzanna"},{"title":"Keep Kupala Night","kind":"ritual","instructions":"Keep Kupala Night with the coven, or on your own if the coven isn’t gathering.\n\nMidsummer night of fire and water: jumping over bonfires, floating flower wreaths on rivers, and searching for the magical fern flower. Kept on St John’s Eve, 23–24 June; in Orthodox lands by the Old Style, 6–7 July.\n\nAfterwards, write what you did, what you noticed, and what Kupala Night means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"slavic/kupala"},{"title":"Keep Dziady","kind":"ritual","instructions":"Keep Dziady with the coven, or on your own if the coven isn’t gathering.\n\nForefathers’ Eve, when the spirits of the ancestors are welcomed home and fed. Kept several times a year in Belarus; the autumn Dziady falls on the Saturday before St Dmitri’s day in early November, and in Poland it has merged with All Saints’ and All Souls’ (1–2 November).\n\nAfterwards, write what you did, what you noticed, and what Dziady means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"slavic/dziady"},{"title":"Keep Koliada","kind":"ritual","instructions":"Keep Koliada with the coven, or on your own if the coven isn’t gathering.\n\nThe season of carolling: koliadki sung from house to house for blessings in the year ahead, traditionally from Christmas Eve to Epiphany (6–19 January by the Old Style). The name comes from the Latin calendae. Keeping it at the solstice as a festival of the newborn sun is a modern Rodnover (Slavic Native Faith) reconstruction; no pre-Christian Koliada is recorded.\n\nAfterwards, write what you did, what you noticed, and what Koliada means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"slavic/koliada"},{"title":"Keep the moons","kind":"attend","instructions":"Leave an offering for the domovoi or the ancestors at each full moon for twelve months.","times":12,"response":"none","checked_by":"mentor"},{"title":"The lore of the year","kind":"study","instructions":"Study the turning year from Koliada to Kupala and Dziady, folk songs and the care of the house spirit. Write a short account in your own words.","times":1,"response":"text","checked_by":"mentor"},{"title":"Divination","kind":"practice","instructions":"Learn one form of divination your coven uses. Do a reading every week for three months and keep a record of what came true.","times":12,"response":"none","checked_by":"self"},{"title":"Relationship with the divine","kind":"reflection","instructions":"Keep a devotional practice to the old gods, the domovoi (house spirit) and the forefathers. At the half-year, write about the relationship as it’s growing.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Service","intro":"A coven is kept by its members. Give your craft and your time to the circle.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Write a page for the coven’s book","kind":"book","instructions":"Write a page for the coven’s Book of Shadows on something you’ve learned this year: a working, a recipe, a piece of lore. Send it for approval.","times":1,"response":"none","checked_by":"manager"},{"title":"Serve at coven rites","kind":"service","instructions":"Help prepare and clear away at two coven rites: setting the altar, bringing what’s needed, welcoming others.","times":2,"response":"none","checked_by":"mentor"},{"title":"Lead a part of a ritual","kind":"ritual","instructions":"Take one part of a coven ritual: calling a quarter, leading a chant, a reading, lighting the altar.","times":1,"response":"none","checked_by":"mentor"},{"title":"A service to the wider community","kind":"service","instructions":"Do something for people or land beyond the coven: a clean-up, a donation, help for someone in need. Write what you did.","times":1,"response":"text","checked_by":"mentor","optional":true}]},{"title":"Dedication and initiation","intro":"The end of the year and a day. You and the coven’s leaders decide together that you are ready.","min_days":0,"passed_by":"manager","tasks":[{"title":"A final conversation with your mentor","kind":"meeting","instructions":"Look back on the year with your mentor: what changed, what’s still to learn, and whether you are ready.","times":1,"response":"none","checked_by":"mentor"},{"title":"Write your oath","kind":"oath","instructions":"Write the oath you will take at your initiation, in your own words, and share it with the coven’s leaders.","times":1,"response":"text","checked_by":"manager"},{"title":"Initiation","kind":"ritual","instructions":"Your initiation into the coven, held by its leaders in the way of Slavic folk practice.","times":1,"response":"none","checked_by":"manager"}]}]'::jsonb, 12)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('slavic-training', 'training', 'slavic', 'Slavic: foundations of the craft', 'Core training for members of a coven following Slavic folk practice, at your own pace.', 'Eight modules of core skills for Slavic folk practice, from energy work to writing a full ritual.

