insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('christian-initiation', 'initiation', 'christian', 'Christian: a year and a day to initiation', 'From seeker to initiate over a year and a day, keeping every feast day of folk Christian and saints’ practice.', 'A traditional year and a day of study, practice and service before initiation, shaped around folk Christian and saints’ practice.

Each stage builds on the one before. Some tasks you sign off yourself; your mentor signs off most; the coven’s leaders confirm the oath and the initiation itself.

Change anything to fit your coven: rename stages, add your own lore, set how long each stage takes, and choose who signs each task off.', '[{"title":"The threshold","intro":"Welcome. In this first stage you meet your mentor, read what the coven holds to, and set down why you seek folk Christian and saints’ practice.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Meet your mentor","kind":"meeting","instructions":"Arrange a first conversation with your mentor. Talk about what drew you here, what you hope to learn, and how you’ll keep in touch through the year.","times":1,"response":"none","checked_by":"mentor"},{"title":"Read the coven’s creed, rules and agreements","kind":"study","instructions":"Read every page the coven has written, and ask your mentor about anything that isn’t clear.","times":1,"response":"none","checked_by":"self"},{"title":"Why I seek this path","kind":"reflection","instructions":"Write a page on why you seek folk Christian and saints’ practice, what you already practise, and what you hope the year will open.","times":1,"response":"text","checked_by":"mentor"},{"title":"Begin a magical diary","kind":"practice","instructions":"Start a diary you’ll keep all year: dreams, workings, moods, the weather, the moon. Write in it at least once a week.","times":1,"response":"none","checked_by":"self"},{"title":"Set up your personal altar","kind":"practice","instructions":"Make a prayer corner with a candle, holy water and images of the saints you keep at home. Describe it, and why you chose what’s on it.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Foundations","intro":"The skills everything else rests on: steadying yourself, keeping your space clean and warded, and making sacred space well.","min_days":90,"passed_by":"mentor","tasks":[{"title":"Ground and centre daily","kind":"practice","instructions":"Ground and centre every day for thirty days: breath, roots, a calm centre. Log each day you do it.","times":30,"response":"none","checked_by":"self","minutes":10},{"title":"Cleanse and ward your home","kind":"practice","instructions":"Cleanse your home and set wards in the coven’s way. Write what you used and how the space felt before and after.","times":1,"response":"text","checked_by":"mentor"},{"title":"Make sacred space","kind":"practice","instructions":"Learn to bless the space with holy water, a candle and prayer. Do it three times, then show your mentor.","times":3,"response":"none","checked_by":"mentor"},{"title":"The elements and the directions","kind":"study","instructions":"Study the elements (or the coven’s equivalent) and their correspondences: directions, colours, tools, times. Write a page for each.","times":1,"response":"text","checked_by":"mentor"},{"title":"Ethics and consent","kind":"reflection","instructions":"Write on the ethics of magic: harm, consent, working for others, and what you will and won’t do. Talk it through with your mentor.","times":1,"response":"text","checked_by":"mentor"},{"title":"Meditation and trance","kind":"practice","instructions":"Practise meditation or light trance twelve times, building from ten minutes to thirty.","times":12,"response":"none","checked_by":"self"}]},{"title":"Turning the year","intro":"A year and a day of folk Christian and saints’ practice. Keep each feast day as it comes and learn the church year, the saints’ days kept in folk custom, and the charms, psalms and blessings of folk practice. This stage lasts at least a year and a day.","min_days":366,"passed_by":"mentor","tasks":[{"title":"Keep Epiphany","kind":"ritual","instructions":"Keep Epiphany with the coven, or on your own if the coven isn’t gathering.\n\nThe Magi come to the Christ child; Twelfth Night ends the Christmas season. Doors are chalked with the year and the Magi’s initials (20 + C + M + B + 27) to bless the house for the year ahead.\n\nAfterwards, write what you did, what you noticed, and what Epiphany means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/epiphany"},{"title":"Keep St Brigid’s Day","kind":"ritual","instructions":"Keep St Brigid’s Day with the coven, or on your own if the coven isn’t gathering.\n\nFeast of Brigid of Kildare, saint of hearth, healing and holy wells. Rush crosses are woven and hung over doors for protection, and a cloth (brat Bríde) is left out overnight to take her blessing.\n\nAfterwards, write what you did, what you noticed, and what St Brigid’s Day means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/st_brigid"},{"title":"Keep Candlemas","kind":"ritual","instructions":"Keep Candlemas with the coven, or on your own if the coven isn’t gathering.\n\nThe Presentation of Christ in the Temple, the light of the world. Candles for the year are blessed today, and the weather is watched for what’s left of winter.\n\nAfterwards, write what you did, what you noticed, and what Candlemas means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/candlemas"},{"title":"Keep Ash Wednesday","kind":"ritual","instructions":"Keep Ash Wednesday with the coven, or on your own if the coven isn’t gathering.\n\nThe first day of Lent, marked with ashes: “remember that you are dust.” Forty days of prayer, fasting and letting go begin.\n\nAfterwards, write what you did, what you noticed, and what Ash Wednesday means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/ash_wednesday"},{"title":"Keep Lady Day (Annunciation)","kind":"ritual","instructions":"Keep Lady Day (Annunciation) with the coven, or on your own if the coven isn’t gathering.\n\nGabriel’s message to Mary, nine months before Christmas. A feast of Mary, of yes-saying and new life, and an old quarter day when the year turned.\n\nAfterwards, write what you did, what you noticed, and what Lady Day (Annunciation) means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/lady_day"},{"title":"Keep Palm Sunday","kind":"ritual","instructions":"Keep Palm Sunday with the coven, or on your own if the coven isn’t gathering.\n\nChrist’s entry into Jerusalem; Holy Week begins. Blessed palms are kept, often folded into crosses, as protection for the home through the year.\n\nAfterwards, write what you did, what you noticed, and what Palm Sunday means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/palm_sunday"},{"title":"Keep Good Friday","kind":"ritual","instructions":"Keep Good Friday with the coven, or on your own if the coven isn’t gathering.\n\nThe crucifixion, the most solemn day of the year: a day of fasting, silence and keeping vigil. Bread baked today was kept for healing.\n\nAfterwards, write what you did, what you noticed, and what Good Friday means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/good_friday"},{"title":"Keep Easter","kind":"ritual","instructions":"Keep Easter with the coven, or on your own if the coven isn’t gathering.\n\nThe resurrection, the heart of the Christian year: new life out of death, kept with sunrise services, eggs, lilies and blessed water.\n\nAfterwards, write what you did, what you noticed, and what Easter means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/easter"},{"title":"Keep Pentecost","kind":"ritual","instructions":"Keep Pentecost with the coven, or on your own if the coven isn’t gathering.\n\nThe Holy Spirit comes as wind and tongues of fire. A feast of gifts, inspiration and speaking with power, fifty days after Easter.\n\nAfterwards, write what you did, what you noticed, and what Pentecost means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/pentecost"},{"title":"Keep St John’s Eve and Day","kind":"ritual","instructions":"Keep St John’s Eve and Day with the coven, or on your own if the coven isn’t gathering.\n\nThe birth of John the Baptist at midsummer. Bonfires are lit on the eve, and St John’s wort, gathered now, is hung for protection.\n\nAfterwards, write what you did, what you noticed, and what St John’s Eve and Day means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/st_john"},{"title":"Keep Lammas (Loaf Mass)","kind":"ritual","instructions":"Keep Lammas (Loaf Mass) with the coven, or on your own if the coven isn’t gathering.\n\nThe first loaf from the new wheat is baked and blessed in thanks for the harvest. Pieces were kept to bless the barn and hearth.\n\nAfterwards, write what you did, what you noticed, and what Lammas (Loaf Mass) means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/lammas"},{"title":"Keep The Assumption of Mary","kind":"ritual","instructions":"Keep The Assumption of Mary with the coven, or on your own if the coven isn’t gathering.\n\nMary taken up into heaven. In many places bundles of healing herbs are blessed today and hung in the house through the year.\n\nAfterwards, write what you did, what you noticed, and what The Assumption of Mary means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/assumption"},{"title":"Keep Michaelmas","kind":"ritual","instructions":"Keep Michaelmas with the coven, or on your own if the coven isn’t gathering.\n\nFeast of St Michael the Archangel, protector against evil, as autumn darkens. Blackberries were not picked after today, and protection is asked for the winter.\n\nAfterwards, write what you did, what you noticed, and what Michaelmas means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/michaelmas"},{"title":"Keep All Hallows’ Eve","kind":"ritual","instructions":"Keep All Hallows’ Eve with the coven, or on your own if the coven isn’t gathering.\n\nThe eve of All Saints, when the boundary with the dead feels thin: candles in windows, prayers for the departed, and the souls remembered.\n\nAfterwards, write what you did, what you noticed, and what All Hallows’ Eve means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/all_hallows_eve"},{"title":"Keep All Saints’ Day","kind":"ritual","instructions":"Keep All Saints’ Day with the coven, or on your own if the coven isn’t gathering.\n\nHonoring all the saints, known and unknown, the great company of the faithful who have gone before.\n\nAfterwards, write what you did, what you noticed, and what All Saints’ Day means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/all_saints"},{"title":"Keep All Souls’ Day","kind":"ritual","instructions":"Keep All Souls’ Day with the coven, or on your own if the coven isn’t gathering.\n\nPrayers for all the faithful departed. Graves are visited and tended, candles lit, and the beloved dead named and remembered.\n\nAfterwards, write what you did, what you noticed, and what All Souls’ Day means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/all_souls"},{"title":"Keep Advent Sunday","kind":"ritual","instructions":"Keep Advent Sunday with the coven, or on your own if the coven isn’t gathering.\n\nThe Christian year begins in waiting for the light. The first candle of the Advent wreath is lit, and one more each Sunday until Christmas.\n\nAfterwards, write what you did, what you noticed, and what Advent Sunday means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/advent"},{"title":"Keep St Lucy’s Day","kind":"ritual","instructions":"Keep St Lucy’s Day with the coven, or on your own if the coven isn’t gathering.\n\nLucy, whose name means light, kept on what was once the longest night: candles, crowns of light and saffron buns carry the light into midwinter.\n\nAfterwards, write what you did, what you noticed, and what St Lucy’s Day means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/st_lucy"},{"title":"Keep Christmas Eve","kind":"ritual","instructions":"Keep Christmas Eve with the coven, or on your own if the coven isn’t gathering.\n\nThe holy night of waiting, kept with candles, midnight services, and the old belief that animals speak at midnight.\n\nAfterwards, write what you did, what you noticed, and what Christmas Eve means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/christmas_eve"},{"title":"Keep Christmas","kind":"ritual","instructions":"Keep Christmas with the coven, or on your own if the coven isn’t gathering.\n\nThe birth of Christ, the light coming into the world at midwinter. The twelve days of Christmas run from today to Epiphany.\n\nAfterwards, write what you did, what you noticed, and what Christmas means to you now.","times":1,"response":"text","checked_by":"mentor","holiday":"christian/christmas"},{"title":"Keep a monthly devotion","kind":"attend","instructions":"Keep a candle and prayer devotion once a month for twelve months, for the saints or the holy dead.","times":12,"response":"none","checked_by":"mentor"},{"title":"The lore of the year","kind":"study","instructions":"Study the church year, the saints’ days kept in folk custom, and the charms, psalms and blessings of folk practice. Write a short account in your own words.","times":1,"response":"text","checked_by":"mentor"},{"title":"Divination","kind":"practice","instructions":"Learn one form of divination your coven uses. Do a reading every week for three months and keep a record of what came true.","times":12,"response":"none","checked_by":"self"},{"title":"Relationship with the divine","kind":"reflection","instructions":"Keep a devotional practice to God, the saints and the holy dead, as your coven’s practice holds them. At the half-year, write about the relationship as it’s growing.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Service","intro":"A coven is kept by its members. Give your craft and your time to the circle.","min_days":0,"passed_by":"mentor","tasks":[{"title":"Write a page for the coven’s book","kind":"book","instructions":"Write a page for the coven’s Book of Shadows on something you’ve learned this year: a working, a recipe, a piece of lore. Send it for approval.","times":1,"response":"none","checked_by":"manager"},{"title":"Serve at coven rites","kind":"service","instructions":"Help prepare and clear away at two coven rites: setting the altar, bringing what’s needed, welcoming others.","times":2,"response":"none","checked_by":"mentor"},{"title":"Lead a part of a ritual","kind":"ritual","instructions":"Take one part of a coven ritual: calling a quarter, leading a chant, a reading, lighting the altar.","times":1,"response":"none","checked_by":"mentor"},{"title":"A service to the wider community","kind":"service","instructions":"Do something for people or land beyond the coven: a clean-up, a donation, help for someone in need. Write what you did.","times":1,"response":"text","checked_by":"mentor","optional":true}]},{"title":"Dedication and initiation","intro":"The end of the year and a day. You and the coven’s leaders decide together that you are ready.","min_days":0,"passed_by":"manager","tasks":[{"title":"A final conversation with your mentor","kind":"meeting","instructions":"Look back on the year with your mentor: what changed, what’s still to learn, and whether you are ready.","times":1,"response":"none","checked_by":"mentor"},{"title":"Write your oath","kind":"oath","instructions":"Write the oath you will take at your initiation, in your own words, and share it with the coven’s leaders.","times":1,"response":"text","checked_by":"manager"},{"title":"Initiation","kind":"ritual","instructions":"Your initiation into the coven, held by its leaders in the way of folk Christian and saints’ practice.","times":1,"response":"none","checked_by":"manager"}]}]'::jsonb, 14)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
    description = excluded.description, stages = excluded.stages, position = excluded.position;
insert into public.coven_program_templates (id, kind, tradition, title, summary, description, stages, position) values ('christian-training', 'training', 'christian', 'Christian: foundations of the craft', 'Core training for members of a coven following folk Christian and saints’ practice, at your own pace.', 'Eight modules of core skills for folk Christian and saints’ practice, from energy work to writing a full ritual.

Members can take the modules alongside an initiation program or on their own. Mentors sign off most tasks; the last module is reviewed by the coven’s leaders.', '[{"title":"Energy and self","intro":"Feel, raise, direct and release energy, and keep yourself clear.","passed_by":"mentor","tasks":[{"title":"Grounding and centring","kind":"practice","instructions":"Practise grounding and centring until you can do it in under a minute. Log ten sessions.","times":10,"response":"none","checked_by":"self"},{"title":"Raising and directing energy","kind":"practice","instructions":"Raise energy by breath, chant or movement, direct it into an object, then release and ground what’s left. Describe what you felt.","times":1,"response":"text","checked_by":"mentor"},{"title":"Shielding","kind":"practice","instructions":"Learn a shielding method and use it every day for a week.","times":7,"response":"none","checked_by":"self"}]},{"title":"Sacred space","intro":"How to bless the space with holy water, a candle and prayer, and how to close it again cleanly.","passed_by":"mentor","tasks":[{"title":"Make and close sacred space","kind":"practice","instructions":"Learn the coven’s way to bless the space with holy water, a candle and prayer. Do it five times.","times":5,"response":"none","checked_by":"mentor"},{"title":"Purification","kind":"practice","instructions":"Learn the coven’s purification before ritual and use it before every working this month.","times":4,"response":"none","checked_by":"self"},{"title":"Write it down","kind":"book","instructions":"Write out the coven’s way of making sacred space as you now do it, for your own book.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Tools and the altar","intro":"The tools your coven uses, how to cleanse and consecrate them, and how to keep an altar.","passed_by":"mentor","tasks":[{"title":"Your altar","kind":"practice","instructions":"Keep a prayer corner with a candle, holy water and images of the saints you keep. Tend it weekly for a month.","times":4,"response":"none","checked_by":"self"},{"title":"Consecrate a tool","kind":"ritual","instructions":"Cleanse and consecrate one working tool. Write what you did and why.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Correspondences, herbs and stones","intro":"What things are for: plants, stones, colours, days and planetary hours.","passed_by":"mentor","tasks":[{"title":"Twelve plants","kind":"study","instructions":"Learn twelve plants your coven works with: their uses, cautions and lore. Keep a page for each.","times":12,"response":"none","checked_by":"self"},{"title":"Seven stones","kind":"study","instructions":"Learn seven stones and how to cleanse and charge them.","times":7,"response":"none","checked_by":"self"},{"title":"Days and hours","kind":"study","instructions":"Learn the planetary days and hours and when to use them. Plan one working by them.","times":1,"response":"text","checked_by":"mentor"},{"title":"Herbal safety","kind":"reflection","instructions":"Write which herbs and oils need care (pregnancy, pets, skin, ingestion) and how you’ll check before using something new.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"Divination","intro":"Read for yourself and, later, for others.","passed_by":"mentor","tasks":[{"title":"Learn a system","kind":"study","instructions":"Choose a system (tarot, runes, ogham, oracle, scrying) and learn its basics.","times":1,"response":"text","checked_by":"mentor"},{"title":"Daily draws","kind":"practice","instructions":"Draw or cast daily for thirty days and note what each meant by evening.","times":30,"response":"none","checked_by":"self"},{"title":"Read for your mentor","kind":"practice","instructions":"Give your mentor a reading and talk through it together.","times":1,"response":"none","checked_by":"mentor"}]},{"title":"Gods, spirits and ancestors","intro":"Build relationship with God, the saints and the holy dead, as your coven’s practice holds them.","passed_by":"mentor","tasks":[{"title":"A devotional practice","kind":"practice","instructions":"Keep a short daily devotion (an offering, a prayer, a candle) for a month.","times":30,"response":"none","checked_by":"self"},{"title":"Honour your ancestors","kind":"ritual","instructions":"Make a place for your ancestors (of blood, of spirit or of craft) and honour them. Write about who you honoured.","times":1,"response":"text","checked_by":"mentor"},{"title":"Discernment","kind":"reflection","instructions":"Write how you tell a real experience from wishful thinking, and when to ask for help.","times":1,"response":"text","checked_by":"mentor"}]},{"title":"The year’s lore","intro":"Learn the church year, the saints’ days kept in folk custom, and the charms, psalms and blessings of folk practice.","passed_by":"mentor","tasks":[{"title":"The lore of Epiphany","kind":"study","instructions":"Learn the history, customs and meaning of Epiphany: The Magi come to the Christ child; Twelfth Night ends the Christmas season. Doors are chalked with the year and the Magi’s initials (20 + C + M + B + 27) to bless the house for the year ahead. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/epiphany"},{"title":"The lore of St Brigid’s Day","kind":"study","instructions":"Learn the history, customs and meaning of St Brigid’s Day: Feast of Brigid of Kildare, saint of hearth, healing and holy wells. Rush crosses are woven and hung over doors for protection, and a cloth (brat Bríde) is left out overnight to take her blessing. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/st_brigid"},{"title":"The lore of Candlemas","kind":"study","instructions":"Learn the history, customs and meaning of Candlemas: The Presentation of Christ in the Temple, the light of the world. Candles for the year are blessed today, and the weather is watched for what’s left of winter. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/candlemas"},{"title":"The lore of Ash Wednesday","kind":"study","instructions":"Learn the history, customs and meaning of Ash Wednesday: The first day of Lent, marked with ashes: “remember that you are dust.” Forty days of prayer, fasting and letting go begin. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/ash_wednesday"},{"title":"The lore of Lady Day (Annunciation)","kind":"study","instructions":"Learn the history, customs and meaning of Lady Day (Annunciation): Gabriel’s message to Mary, nine months before Christmas. A feast of Mary, of yes-saying and new life, and an old quarter day when the year turned. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/lady_day"},{"title":"The lore of Palm Sunday","kind":"study","instructions":"Learn the history, customs and meaning of Palm Sunday: Christ’s entry into Jerusalem; Holy Week begins. Blessed palms are kept, often folded into crosses, as protection for the home through the year. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/palm_sunday"},{"title":"The lore of Good Friday","kind":"study","instructions":"Learn the history, customs and meaning of Good Friday: The crucifixion, the most solemn day of the year: a day of fasting, silence and keeping vigil. Bread baked today was kept for healing. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/good_friday"},{"title":"The lore of Easter","kind":"study","instructions":"Learn the history, customs and meaning of Easter: The resurrection, the heart of the Christian year: new life out of death, kept with sunrise services, eggs, lilies and blessed water. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/easter"},{"title":"The lore of Pentecost","kind":"study","instructions":"Learn the history, customs and meaning of Pentecost: The Holy Spirit comes as wind and tongues of fire. A feast of gifts, inspiration and speaking with power, fifty days after Easter. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/pentecost"},{"title":"The lore of St John’s Eve and Day","kind":"study","instructions":"Learn the history, customs and meaning of St John’s Eve and Day: The birth of John the Baptist at midsummer. Bonfires are lit on the eve, and St John’s wort, gathered now, is hung for protection. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/st_john"},{"title":"The lore of Lammas (Loaf Mass)","kind":"study","instructions":"Learn the history, customs and meaning of Lammas (Loaf Mass): The first loaf from the new wheat is baked and blessed in thanks for the harvest. Pieces were kept to bless the barn and hearth. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/lammas"},{"title":"The lore of The Assumption of Mary","kind":"study","instructions":"Learn the history, customs and meaning of The Assumption of Mary: Mary taken up into heaven. In many places bundles of healing herbs are blessed today and hung in the house through the year. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/assumption"},{"title":"The lore of Michaelmas","kind":"study","instructions":"Learn the history, customs and meaning of Michaelmas: Feast of St Michael the Archangel, protector against evil, as autumn darkens. Blackberries were not picked after today, and protection is asked for the winter. Write a short page of what you found.","times":1,"response":"text","checked_by":"self","holiday":"christian/michaelmas"}]},{"title":"Ritual craft","intro":"Bring it all together: write and lead a ritual of your own.","passed_by":"manager","tasks":[{"title":"Write a ritual","kind":"book","instructions":"Write a complete ritual for the coven: its purpose, sacred space, the working, the words and the closing.","times":1,"response":"text","checked_by":"manager"},{"title":"Lead it","kind":"ritual","instructions":"Lead your ritual for the coven or a few members, with your mentor present.","times":1,"response":"none","checked_by":"manager"},{"title":"Look back","kind":"reflection","instructions":"Write what went well, what you’d change, and what the training has given you.","times":1,"response":"text","checked_by":"mentor"}]}]'::jsonb, 15)
  on conflict (id) do update set kind = excluded.kind, tradition = excluded.tradition, title = excluded.title, summary = excluded.summary,
